// Extract payment details from Stripe webhook
const paymentIntent = $input.item.json.data.object;

// Extract key details
const amount = paymentIntent.amount; // Amount in cents
const currency = paymentIntent.currency.toUpperCase();
const customerEmail = paymentIntent.receipt_email || 
                       paymentIntent.charges?.data?.[0]?.billing_details?.email || 
                       'N/A';
const paymentId = paymentIntent.id;
const status = paymentIntent.status;

// Format amount (convert cents to dollars/euros/etc)
const formattedAmount = (amount / 100).toFixed(2);

// Return formatted data for next node
return {
  json: {
    amount: formattedAmount,
    currency: currency,
    customerEmail: customerEmail,
    paymentId: paymentId,
    status: status,
    dashboardUrl: `https://dashboard.stripe.com/payments/${paymentId}`
  }
};

